def calc_month_span(date_str: str):
    """Calculate month span from a date range string.

    Accepts:
      - '2026.08 ~ 2026.10'
      - '2026-08 ~ 2026-10'
      - '2026/08 ~ 2026/10'
      - single month: '2027-01' / '2027.01' / '2027/01' (returns 1)
